style.css:
@-moz-document domain("roblox.com") {
/* Force GIF background on body */
  body, html {
    background: url("https://i.pinimg.com/originals/81/42/e8/8142e82c23cf616509361fd0abb018c2.gif") 
      no-repeat center top !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Roblox's giant white background layer — REMOVE IT */
  #container-main,
  #rbx-body,
  .content,
  .page-content,
  .page-content-container,
  .container-main,
  .theme-container,
  .content-area {
    background: transparent !important;
  }

  /* The huge white panels you circled */
  .home-container,
  .connections-container,
  .games-list-container,
  .stack,
  .section,
  .ng-scope {
    background-color: transparent !important;
  }

  /* Prevent Roblox from re-painting white backgrounds */
  div, section {
    background-color: transparent !important;
  }

  /* Keep header + sidebar normal (dark) */
  header,
  nav,
  #navigation,
  .left-col {
    background-color: #111 !important;
  }
}
